import { useState } from 'react';
import productsData from '../fixtures/products.json';
import { filterProducts, sortProducts, Product } from './utils';

const products = productsData as Product[];

export default function App() {
  const [search, setSearch] = useState("");
  const [category, setCategory] = useState("All");
  const [sortOrder, setSortOrder] = useState("");
  const [page, setPage] = useState(1);

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearch(e.target.value);
    setPage(1);
  };

  const handleCategoryChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setCategory(e.target.value);
    setPage(1);
  };

  const handleSortChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSortOrder(e.target.value);
  };

  const filteredProducts = filterProducts(products, search, category);
  const sortedProducts = sortProducts(filteredProducts, sortOrder);

  const itemsPerPage = 10;
  const totalPages = Math.ceil(sortedProducts.length / itemsPerPage);

  const currentPage = Math.max(1, Math.min(page, totalPages === 0 ? 1 : totalPages));

  const startIndex = (currentPage - 1) * itemsPerPage;
  const paginatedProducts = sortedProducts.slice(startIndex, startIndex + itemsPerPage);

  return (
    <main>
      <h1>Catálogo de Productos</h1>

      <div>
        <label htmlFor="search">Buscar</label>
        <input 
          id="search"
          type="search" 
          value={search} 
          onChange={handleSearchChange} 
        />
      </div>

      <div>
        <label htmlFor="category">Categoría</label>
        <select 
          id="category"
          value={category}
          onChange={handleCategoryChange}
        >
          <option value="All">All</option>
          <option value="Electronics">Electronics</option>
          <option value="Home">Home</option>
          <option value="Sports">Sports</option>
          <option value="Books">Books</option>
        </select>
      </div>

      <div>
        <label htmlFor="sortOrder">Orden</label>
        <select 
          id="sortOrder"
          value={sortOrder}
          onChange={handleSortChange}
        >
          <option value="">Sin orden</option>
          <option value="name-asc">name-asc</option>
          <option value="name-desc">name-desc</option>
          <option value="price-asc">price-asc</option>
          <option value="price-desc">price-desc</option>
        </select>
      </div>

      <div>
        {sortedProducts.length === 0 ? (
          <p>No hay resultados</p>
        ) : (
          <>
            <ul>
              {paginatedProducts.map(p => (
                <li key={p.id}>{p.id} {p.name}</li>
              ))}
            </ul>
            <div>
              <button 
                onClick={() => setPage(currentPage - 1)} 
                disabled={currentPage <= 1}
              >
                Anterior
              </button>
              <button 
                onClick={() => setPage(currentPage + 1)} 
                disabled={currentPage >= totalPages}
              >
                Siguiente
              </button>
            </div>
          </>
        )}
      </div>
    </main>
  );
}

export interface Product {
  id: string;
  name: string;
  category: string;
  price: number;
}

export function filterProducts(products: Product[], search: string, category: string): Product[] {
  const searchClean = search.trim().toLowerCase();
  return products.filter(product => {
    const categoryMatch = category === "All" || product.category === category;
    const searchMatch = searchClean === "" || product.name.toLowerCase().includes(searchClean);
    return categoryMatch && searchMatch;
  });
}

export function sortProducts(products: Product[], sortOrder: string): Product[] {
  if (!sortOrder) return products;

  const sorted = [...products];

  sorted.sort((a, b) => {
    if (sortOrder === "name-asc") {
      const nameA = a.name.toLowerCase();
      const nameB = b.name.toLowerCase();
      return nameA < nameB ? -1 : nameA > nameB ? 1 : 0;
    } else if (sortOrder === "name-desc") {
      const nameA = a.name.toLowerCase();
      const nameB = b.name.toLowerCase();
      return nameA > nameB ? -1 : nameA < nameB ? 1 : 0;
    } else if (sortOrder === "price-asc") {
      return a.price - b.price;
    } else if (sortOrder === "price-desc") {
      return b.price - a.price;
    }
    return 0;
  });

  return sorted;
}

